@LinearIndependent.span_eq_top_of_card_eq_finrank' : ∀ {K : Type u} {V : Type v} [inst : DivisionRing.{u} K] [inst_1 : AddCommGroup.{v} V]
  [inst_2 : _root_.Module.{u, v} K V] {ι : Type u_1} [inst_3 : Fintype.{u_1} ι] [FiniteDimensional.{u, v} K V]
  {b : ι → V},
  LinearIndependent.{u_1, u, v} K b →
    Eq.{1} (Fintype.card.{u_1} ι) (Module.finrank.{u, v} K V) →
      Eq.{v + 1} (Submodule.span.{u, v} K (Set.range.{v, u_1 + 1} b)) Top.top.{v}

@Module.finrank_eq_card_basis : ∀ {R : Type u} {M : Type v} [inst : Semiring.{u} R] [inst_1 : AddCommMonoid.{v} M] [inst_2 : _root_.Module.{u, v} R M]
  [StrongRankCondition.{u} R] {ι : Type w} [inst_4 : Fintype.{w} ι] (h : Module.Basis.{w, u, v} ι R M),
  Eq.{1} (Module.finrank.{u, v} R M) (Fintype.card.{w} ι)

@LinearEquiv.finrank_eq : ∀ {R : Type u} {M : Type v} {N : Type w} [inst : Semiring.{u} R] [inst_1 : AddCommMonoid.{v} M]
  [inst_2 : _root_.Module.{u, v} R M] [inst_3 : AddCommMonoid.{w} N] [inst_4 : _root_.Module.{u, w} R N]
  (f : LinearEquiv.{u, u, v, w} (RingHom.id.{u} R) M N), Eq.{1} (Module.finrank.{u, v} R M) (Module.finrank.{u, w} R N)

@Nat.exists_eq_pow_mul_and_not_dvd : ∀ {n : ℕ},
  Ne.{1} n 0 →
    ∀ (p : ℕ), Ne.{1} p 1 → ∃ e n', ¬Dvd.dvd.{0} p n' ∧ Eq.{1} n (HMul.hMul.{0, 0, 0} (HPow.hPow.{0, 0, 0} p e) n')

@FiniteDimensional.span_of_finite : ∀ (K : Type u) {V : Type v} [inst : DivisionRing.{u} K] [inst_1 : AddCommGroup.{v} V]
  [inst_2 : _root_.Module.{u, v} K V] {A : Set.{v} V},
  Set.Finite.{v} A → FiniteDimensional.{u, v} K ↥(Submodule.span.{u, v} K A)

